    def sum_divisors(x):
        total = 1
        for i in range(2, int(x**0.5) + 1):
            if x % i == 0:
                total += i + x // i
        return total

    amicable_sum = 0
    for i in range(2, n + 1):
        j = sum_divisors(i)
        if i != j and sum_divisors(j) == i and j <= n:
            amicable_sum += i
    return amicable_sum

